#include <iostream>
#include <vector>
#include <numeric>

int main() {
    using namespace std;

    unsigned N;
    cin >> N;

    // 列を base からの差分で管理
    vector<unsigned long> A(N);
    unsigned base{};

    for (auto &&a : A)cin >> a;
    A.emplace(begin(A));

    // 差分が 0 でないかもしれない場所
    // はじめは 1, ..., N すべて
    vector<unsigned> added_index(N);
    iota(begin(added_index), end(added_index), 1U);

    unsigned Q;
    cin >> Q;

    for (unsigned _{}; _ < Q; ++_) {
        unsigned type;
        cin >> type;
        if (type == 1) {
            // 差分が 0 でないところを消去
            while (!empty(added_index)) {
                A[added_index.back()] = 0;
                added_index.pop_back();
            }
            cin >> base;
        } else if (type == 2) {
            // index 番目の差分に加える
            unsigned index, value;
            cin >> index >> value;
            A[index] += value;
            added_index.emplace_back(index);
        } else {
            // base に index 番目の差分を加える
            unsigned index;
            cin >> index;
            cout << base + A[index] << endl;
        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <utility>

int main() {
    using namespace std;

    unsigned N;
    cin >> N;

    // 列を base からの差分と最終更新時刻を管理
    vector<pair<unsigned long, unsigned>> A(N);
    pair<unsigned, unsigned> base{};

    for (auto &&[a, _] : A)cin >> a;
    A.emplace(begin(A));

    unsigned Q;
    cin >> Q;

    for (unsigned q{1}; q <= Q; ++q) {
        unsigned type;
        cin >> type;
        if (type == 1) {
            // base を読み込み、時刻を更新
            cin >> base.first;
            base.second = q;
        } else if (type == 2) {
            // index 番目の差分に加え、時刻を更新
            unsigned index, value;
            cin >> index >> value;
            if (A[index].second < base.second)A[index].first = value;
            else A[index].first += value;
            A[index].second = q;
        } else {
            // base に index 番目の差分を加える
            unsigned index;
            cin >> index;
            if (A[index].second < base.second)cout << base.first << endl;
            else cout << base.first + A[index].first << endl;
        }
    }

    return 0;
}

#include <iostream>
